pub(crate) fn collect_doctor_source_inventory(
    data_dir: &Path,
    db_path: &Path,
) -> DoctorSourceInventoryReport {
    let home = dirs::home_dir().unwrap_or_default();
    let config_dir = dirs::config_dir().unwrap_or_else(|| data_dir.to_path_buf());
    let detected_roots: Vec<_> = diagnostics_connector_paths(&home, &config_dir)
        .into_iter()
        .filter(|(_, path)| {
            let under = |base: &Path| !base.as_os_str().is_empty() && path.starts_with(base);
            under(&home) || under(&config_dir) || under(data_dir)
        })
        .collect();
    if !db_path.exists() {
        return build_doctor_source_inventory_report(
            data_dir,
            false,
            None,
            Vec::new(),
            detected_roots,
        );
    }

    let query_result = open_franken_cli_read_db(
        db_path.to_path_buf(),
        "doctor source inventory",
        Duration::from_secs(1),
    )
    .and_then(|conn| {
        let query_result = query_doctor_source_inventory_db_rows(&conn).map_err(|e| CliError {
            code: 9,
            kind: CliErrorKind::DbQuery.kind_str(),
            message: format!("Failed to query doctor source inventory: {e}"),
            hint: None,
            retryable: false,
        });
        let close_result = close_franken_cli_read_db(conn, db_path, "doctor source inventory");
        match (query_result, close_result) {
            (Ok(rows), Ok(())) => Ok(rows),
            (Err(err), _) | (_, Err(err)) => Err(err),
        }
    });

    match query_result {
        Ok(rows) => {
            build_doctor_source_inventory_report(data_dir, true, None, rows, detected_roots)
        }
        // The DB file exists but could not be read (unopenable/malformed, or a
        // read timeout). `db_available` must reflect *readability*, not mere
        // existence: reporting `true` here laundered a failed open into an
        // "available archive" whose default 0-row count was then promoted into
        // `archive-db-opened` evidence and selected as repair authority over a
        // checksum-verified raw mirror (#374 Issue 1). The `db_query_error`
        // below still surfaces the concrete failure to the operator.
        Err(err) => build_doctor_source_inventory_report(
            data_dir,
            false,
            Some(err.message),
            Vec::new(),
            detected_roots,
        ),
    }
}

pub(crate) fn doctor_source_inventory_deferred(reason: &str) -> DoctorSourceInventoryReport {
    DoctorSourceInventoryReport {
        schema_version: 1,
        db_available: false,
        db_query_error: Some(reason.to_string()),
        notes: vec![
            "Archive-wide source inventory was not attempted; zero-valued coverage fields are unknown, not evidence of absence."
                .to_string(),
        ],
        ..DoctorSourceInventoryReport::default()
    }
}

pub(crate) fn doctor_sources_config_path(data_dir: &Path) -> PathBuf {
    doctor_sources_config_path_from_config_result(
        data_dir,
        crate::sources::config::SourcesConfig::config_path(),
    )
}

pub(crate) fn doctor_sources_config_path_from_config_result(
    data_dir: &Path,
    config_path: Result<PathBuf, crate::sources::config::ConfigError>,
) -> PathBuf {
    config_path.unwrap_or_else(|_| data_dir.join("cass").join("sources.toml"))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DoctorSourcesConfigCheck {
    pub(crate) status: &'static str,
    pub(crate) message: String,
}

pub(crate) fn doctor_sources_config_check(sources_path: &Path) -> DoctorSourcesConfigCheck {
    if !sources_path.exists() {
        return DoctorSourcesConfigCheck {
            status: "pass",
            message: "No remote sources configured".to_string(),
        };
    }

    let content = match std::fs::read_to_string(sources_path) {
        Ok(content) => content,
        Err(e) => {
            return DoctorSourcesConfigCheck {
                status: "warn",
                message: format!("Cannot read sources config: {e}"),
            };
        }
    };

    match toml::from_str::<crate::sources::config::SourcesConfig>(&content) {
        Ok(config) => match config.validate() {
            Ok(()) => DoctorSourcesConfigCheck {
                status: "pass",
                message: "Sources config valid".to_string(),
            },
            Err(e) => DoctorSourcesConfigCheck {
                status: "warn",
                message: format!("Sources config validation warning: {e}"),
            },
        },
        Err(e) => DoctorSourcesConfigCheck {
            status: "warn",
            message: format!("Sources config parse error: {e}"),
        },
    }
}
